final class Parser {
    private final Map<Long, Memo> memo = new HashMap<>();

    Memo rule(int ruleId, int pos) {
        long key = ((long) ruleId << 32) | pos;
        Memo hit = memo.get(key);
        if (hit != null) return hit;        // success or recorded failure
        Memo m = ruleImpl(ruleId, pos);     // may backtrack
        memo.put(key, m);                   // failures are memoized too
        return m;
    }
}
